use std::io::*;use std::collections::HashMap;
fn main(){let mut s=String::new();stdin().read_to_string(&mut s).unwrap();let mut m:HashMap<String,i64>=HashMap::new();for l in s.lines(){let p:Vec<&str>=l.split_whitespace().collect();if p.len()<2{continue;}let n=p[1].to_string();match p[0]{"deposit"=>{let a:i64=p[2].parse().unwrap_or(0);*m.entry(n).or_insert(0)+=a;}"withdraw"=>{let a:i64=p[2].parse().unwrap_or(0);let b=m.entry(n.clone()).or_insert(0);if *b<a{println!("error: insufficient funds for {}",n);}else{*b-=a;}}"balance"=>{println!("{} {}",n,m.get(&n).copied().unwrap_or(0));}_=>{}}}}
